begin;
create extension if not exists pgtap with schema extensions;
select plan(13);
insert into public.work_cards(company_id,stage_id,title) select company_id,id,'Other company' from public.work_stages where company_id='10000000-0000-0000-0000-000000000003' and position=1;
select set_config('test.other_card',(select id::text from public.work_cards where title='Other company'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select lives_ok($$insert into public.work_card_visits(company_id,person_id,card_id,opened_at) values ('10000000-0000-0000-0000-000000000001',auth.uid(),1,'2000-01-01')$$,'Viewer can record an opened card');
select ok((select opened_at>now()-interval '1 minute' from public.work_card_visits where card_id=1),'visit time comes from the database');
select lives_ok($$insert into public.work_card_visits(company_id,person_id,card_id) values ('10000000-0000-0000-0000-000000000001',auth.uid(),1) on conflict(company_id,person_id,card_id) do update set opened_at=excluded.opened_at$$,'reopening upserts one visit');
select is((select count(*)::int from public.work_card_visits),1,'one entry per person and card');
select throws_ok($$insert into public.work_card_visits(company_id,person_id,card_id) values ('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000005',2)$$,'42501',null,'cannot forge another person history');
select throws_ok($$insert into public.work_card_visits(company_id,person_id,card_id) values ('10000000-0000-0000-0000-000000000003',auth.uid(),current_setting('test.other_card')::bigint)$$,'42501',null,'cannot record another company without membership');
select throws_ok($$insert into public.work_card_visits(company_id,person_id,card_id) values ('10000000-0000-0000-0000-000000000001',auth.uid(),current_setting('test.other_card')::bigint)$$,'23503',null,'composite foreign key rejects a card from another company');
select throws_ok($$update public.work_card_visits set card_id=2 where card_id=1$$,'P0001','visit identity cannot change','visit identity is immutable');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',true);
select is((select count(*)::int from public.work_card_visits),0,'same company member cannot read another person history');
with changed as (update public.work_card_visits set opened_at=now() returning 1) select is((select count(*)::int from changed),0,'cannot change another person history');
select lives_ok($$insert into public.work_card_visits(company_id,person_id,card_id) values ('10000000-0000-0000-0000-000000000003',auth.uid(),current_setting('test.other_card')::bigint)$$,'multi-company member can record their other company');
reset role;
update public.members set removed_at=now() where person_id='20000000-0000-0000-0000-000000000005' and company_id='10000000-0000-0000-0000-000000000003';
set local role authenticated;
select is((select count(*)::int from public.work_card_visits),0,'removed membership hides history');
set local role anon;
select is((select count(*)::int from public.work_card_visits),0,'anonymous cannot read history');
select * from finish();
rollback;
